# given — read it and use it, no need to change it
def declination_deg(lat, lon, year, alt_km=0.0):
    """The magnetic declination (degrees, positive EAST) at a place and time from the World Magnetic Model
    (WMM2025, valid 2025–2030), through the pygeomag package. lat, lon in degrees; year as a decimal year
    (15 October 2026 ≈ 2026.79); alt_km above sea level.

    Example: declination_deg(51.50, -0.12, 2026.79) → about 1.21   (London)
    """
    from pygeomag import GeoMag
    return float(GeoMag().calculate(glat=float(lat), glon=float(lon), alt=float(alt_km), time=float(year)).d)


