    """Watches a sensor's samples and says when the data is FROZEN: the same sample, repeated exactly,
    max_repeat times in a row (a real sensor's noise changes at least one digit at every sample). Feed it
    every sample with update(). From mission 17; NAVERA's own rule is described in the lesson."""

    # given — read it and use it, no need to change it
    def __init__(self, max_repeat=50):
        """max_repeat: how many exact repeats in a row mean "frozen" (an int ≥ 1). The detector starts
        with no sample seen: self.last = None (the previous sample, as a tuple of floats) and
        self.repeats = 0 (how many times in a row it has been repeated so far)."""
        if int(max_repeat) != max_repeat or max_repeat < 1:
            raise ValueError(f"max_repeat must be an int >= 1, got {max_repeat!r}")
        self.max_repeat = int(max_repeat)
        self.last = None
        self.repeats = 0

